package com.travbook.cabs.adapter.out.supplier;
import com.travbook.cabs.application.port.out.CabSupplier;
import com.travbook.cabs.domain.model.Cab;
import com.travbook.cabs.domain.model.Cab.*;
import com.travbook.shared.domain.*;
import com.travbook.shared.adapter.out.supplier.BoundedDiscovery;
import java.time.*;
import java.math.*;
import java.util.*;
public final class MockCabSupplier implements CabSupplier{
 private final BoundedDiscovery calls;public MockCabSupplier(BoundedDiscovery calls){this.calls=calls;}
 public Inventory search(Criteria c,Instant now){if(c.returnAt()!=null&&Duration.between(c.pickupAt(),c.returnAt()).toHours()<Math.max(3,(distance(c)*2+49)/50))throw new DomainFailure(DomainFailure.Code.VALIDATION_FAILED,"Round-trip schedule is shorter than the simulated route duration.");var batch=calls.collect("cab",List.of("sample-transfer","sample-drive"),p->{if(c.pickup()==Place.JAIPUR_CENTRE||p.equals("sample-drive")&&c.pickup()==Place.GOA_AIRPORT)throw new IllegalStateException("Simulated cab outage");int distance=distance(c);if(distance==0)return List.<Offer>of();var result=new ArrayList<Offer>();for(var category:Category.values()){var o=price(c,UUID.randomUUID(),p,category,false);if(c.passengers()<=o.passengerCapacity()&&c.luggage()<=o.luggageCapacity())result.add(o);}return result;});return new Inventory(batch.items(),batch.coverage());}
 private int distance(Criteria c){if(c.type()==Type.LOCAL)return c.hours()*10;if(c.type()==Type.AIRPORT)return 28;var pair=Set.of(Cab.city(c.pickup()),Cab.city(c.dropoff()));if(pair.equals(Set.of("DELHI","JAIPUR")))return 270;if(pair.equals(Set.of("DELHI","AGRA")))return 230;if(pair.equals(Set.of("MUMBAI","PUNE")))return 150;return 0;}
 private Offer price(Criteria c,UUID id,String supplier,Category category,boolean refresh){int oneWay=distance(c),km=oneWay*(c.type()==Type.OUTSTATION_ROUND_TRIP?2:1);int hours=c.type()==Type.LOCAL?c.hours():c.returnAt()!=null?Math.toIntExact(Duration.between(c.pickupAt(),c.returnAt()).toHours()):Math.max(1,(oneWay+49)/50);if(c.returnAt()!=null&&hours<Math.max(3,(km+49)/50))throw new DomainFailure(DomainFailure.Code.VALIDATION_FAILED,"Round-trip schedule is shorter than the simulated route duration.");int rate=switch(category){case HATCHBACK->12;case SEDAN->16;case SUV->22;};BigDecimal base=BigDecimal.valueOf((long)km*rate+hours*20L+(supplier.equals("sample-drive")?100:0)+(refresh&&category==Category.SUV?100:0));BigDecimal tax=base.multiply(new BigDecimal("0.10")).setScale(2,RoundingMode.HALF_UP);var fees=TravelMoney.inr(50);return new Offer(id,supplier,category,category==Category.HATCHBACK?3:category==Category.SEDAN?4:6,category==Category.HATCHBACK?2:category==Category.SEDAN?3:6,km,km,hours,c.pickupAt(),c.returnAt(),"Asia/Kolkata",TravelMoney.inr(base),TravelMoney.inr(tax),fees,TravelMoney.inr(base.add(tax).add(fees.decimal())),TravelMoney.inr(rate),TravelMoney.inr(150),List.of("Quoted kilometre/hour bundle","Simulated driver allowance","Synthetic 10% tax and service fee"),List.of("Tolls and parking: charged separately if incurred","Extra kilometres/hours at displayed rates","No live routing, driver or registration allocation"),"MOCK cancellation policy preview: free before 24 hours to pickup; later eligibility requires a provider quotation. No reservation exists in this slice.","Deterministic route estimate, not navigation: "+km+" km / "+hours+" hours. Amount includes the stated bundle only; actual extras are not yet known.");}
 public Offer reprice(Criteria c,Offer before,Instant now){return calls.one("cab",before.supplier(),()->price(c,before.id(),before.supplier(),before.category(),true));}
}
